<?php
require __DIR__.'/bootstrap.php';$error='';if($_SERVER['REQUEST_METHOD']==='POST')try{check_csrf();$st=db()->prepare('SELECT * FROM cg_admin WHERE username=?');$st->execute([trim((string)($_POST['username']??''))]);$u=$st->fetch();if(!$u||!password_verify((string)($_POST['password']??''),$u['password_hash']))throw new RuntimeException('로그인 정보를 확인하세요.');session_regenerate_id(true);$_SESSION['admin']=$u['id'];redirect();}catch(Throwable $e){$error=$e->getMessage();}?>
